import base64,concurrent.futures,json,math,statistics
from pathlib import Path
from audit_stability import HOSTS
from inspect_realtime import WORK
from deploy import remote
from write_stability_report import COPY
from build_realtime_release import ROOT,VERSION,NETWORK_RELEASE

REPORT=Path(__file__).resolve().parents[1]/'GROUP_REALTIME_2026-10-05_RU.md'

def main():
    result=json.loads((WORK/'verification-summary.json').read_text());integration=result['integration']
    delays=sorted(x['ms'] for x in integration['received'])
    lines=['# Быстрая индикация группы и резерв RS485 — 05.10.2026','',
      'Установлены Raspberry release `'+result['firmware']+'`, bundle `'+VERSION+'` и сеть `'+result['network']+'` на всех девяти доступных системных разделах пяти приборов.','',
      '## Поведение','',
      '- В строке **LED pattern** групповой таблицы отображаются только числа 0–15. Выбранный паттерн сохраняется при отсутствии детекции; 0 — тёмный паттерн.',
      '- Подтверждённый результат ADC публикуется на Raspberry сразу после решения детектора, перед DC-adapt, сохранением детекции, оптическим gate, LED, реле и отправкой статуса в STM32. Выключение также публикуется перед остановкой выходов.',
      '- Между Raspberry работают постоянные подписанные TCP-потоки изменений; UDP остаётся дополнительным каналом доставки. Браузер получает изменения через настоящий [WebSocket, RFC 6455](https://www.rfc-editor.org/rfc/rfc6455).',
      '- Неизменённое состояние повторяется для контроля свежести примерно раз в секунду. При живом WebSocket HTTP-снимок общих сведений выполняется раз в пять секунд.',
      '- При потере быстрого состояния конкретного соседа действует прежний TTL 4 секунды, после чего индикация берётся из подтверждённых данных STM32/RS485. Браузер сразу запрашивает их и продолжает опрос каждые 0,5 секунды. При потере WebSocket также включается HTTP-опрос; попытки восстановления выполняются с интервалом 1–5 секунд.',
      '- RS485-синхронизация выполняется постоянно под управлением STM32, включая время работы быстрого канала. Оптическая привязка не переназначается при обрыве связи. Удалённые изменения параметров требуют живого быстрого канала.',
      '- Очереди ограничены 256 событиями. Медленный или отсутствующий подписчик не задерживает USB-владельца; при переполнении выполняется восстановление по последнему полному состоянию. Это событийная доставка с контролем свежести, а не гарантия жёсткого времени исполнения.',
      '- Пороги, подтверждения, фильтры, HOLD, правила LED/звука/реле и прошивка STM32 не изменялись. DetADC отображает подтверждённый сигнал детектора с существующим удержанием, а не сырую форму ADC.','',
      '## Почему раньше было медленно','',
      'Отображение последовательно ожидало запись USB-кэша, групповой снимок, публикацию принятого пакета и очередной HTTP-опрос браузера. Эти участки выполнялись примерно раз в 0,5 секунды и суммировали задержку. Кроме того, индикация ADC зависела от отправки результата в STM32 и его обратного статуса. Теперь получение результата браузером отделено от этих ожиданий.','',
      '## Проверки','',
      '**44 Python-теста PASS на каждом из девяти разделов**, включая криптографию и проверку порядка публикации перед STM32-зависимыми операциями. Проверены короткие включения/выключения, устаревшие поколения кэша, последовательности, перезапуск источника, ограничение очереди, Origin и авторизация WebSocket. JavaScript-проверки подтверждают порядок событий, восстановление HTTP и возврат ADC к данным RS485. Все семь скриптов отрендеренной страницы разбираются без ошибок.','',
      'Изолированный тест на S13 использует реальные новые USB-cache методы без открытия USB, Unix-сокет, подписанный TCP-поток между двумя тестовыми узлами и реальный обработчик портала/WebSocket. 20 изменений с интервалом 20 мс дошли в порядке отправки без потерь. Временные файлы размещены в RAM, как рабочий `/run`; оба тестовых узла работают на одном Raspberry, соединение loopback. Задержка: p50 '+str(statistics.median(delays))+' мс, p95 '+str(delays[math.ceil(.95*len(delays))-1])+' мс, максимум '+str(max(delays))+' мс. **Это не измерение Wi-Fi, отрисовки браузера или времени от физического прохода метки.**','',
      'В настоящем браузере открытая групповая страница S13 показывает `Live · WebSocket`, пять устройств и числовые значения LED. Проверка непосредственного браузера S12 не выполнялась; одинаковые файлы портала проверены SHA-256 на всех разделах. Снимок: `.tmp/group-realtime-20261005/group-final.png`.','',
      'После итоговой установки выполнено одновременное наблюдение пяти действующих приборов по 90 секунд, 360 снимков с интервалом 250 мс.','',
      '| Наблюдатель | Снимки | Пропавшие / недоступные | Новые gaps / CRC / magic / ACK | Кадры ADC1 / ADC2 |',
      '|---|---:|---|---|---|']
    for board,value in result['observation'].items():
        delta=value['stream_delta'];lines.append('| '+board+' | '+str(value['samples'])+' | 0 / 0 | 0 / 0 / 0 / 0 | '+str(delta['rx_cnt_ch0'])+' / '+str(delta['rx_cnt_ch1'])+' |')
    lines += ['', 'Карта группы остаётся `0x00003C02`; настройки реакций и привязки оптики постоянны во всех снимках. Физические проходы меток и принудительные отключения Wi-Fi/RS485 в этом задании не выполнялись. Задержку алгоритма и реальную задержку детекции на метке эта проверка не устанавливает.','',
      '## Версии и носители','', '| Прибор | eMMC | USB | Работающая система |','|---|---|---|']
    for board in HOSTS:
        lines.append('| '+board+' | '+VERSION+' / '+result['network']+' | '+('Не подключён' if board=='S12' else VERSION+' / '+result['network'])+' | '+('eMMC' if board=='S12' else 'USB')+' |')
    lines += ['', 'На каждом разделе совпадают 22 модуля приложения, три копии портала, метаданные release и все файлы сетевого манифеста. 19 прежних модулей приложения побайтово сохранены; изменены публикация в engine и USB stream, добавлен owner_events.py. Настройки каждого раздела сохранены индивидуально. Core перезапускался для загрузки уведомителя и при уточнении публикации перед выходами; во время финального наблюдения поток непрерывен.','',
      'В `bmi30_sel.json` служба при запуске и восстановлении режима обновляет только служебное поле времени `ts`; значение `sel` и остальные параметры проверены против резервной копии. Файлы основной конфигурации, реле и сетевой конфигурации совпадают побайтово. Первая пробная установка S13 была автоматически отменена из-за проверки этого timestamp; выбранный режим не менялся.','',
      'Работающие M01/S10/S11/S13 проверены с USB `/dev/sda2`, S12 — с eMMC `/dev/mmcblk0p2`. Резервные eMMC четырёх приборов проверены по файлам и Linux-тестам без нового загрузочного теста. Полная идентичность ОС не заявляется.','',
      '## Резервные копии','', '| Прибор | Раздел | Резервная копия |','|---|---|---|']
    for root in result['roots']:lines.append('| '+root['board']+' | '+root['device']+' | /'+root['backup']+' |')
    lines += ['', 'Резервные копии конфигураций и заменённых файлов остаются на приборах и не экспортируются. Пакеты: `FirmwareReleases/RaspberryPi/'+VERSION+'/` и `'+NETWORK_RELEASE+'/`; контрольные суммы в SHA256SUMS. Архивы не опубликованы на сервере обновления. Промежуточная сеть 0.1.8 помечена «Не устанавливать», исправленная версия 0.1.11 установлена везде.','',
      'Полные данные проверки: `.tmp/group-realtime-20261005/verification-summary.json`, `integration.json`, `*-observation.json`, `*-inventory-after.json`, `*-install.json`.','']
    REPORT.write_text('\n'.join(lines),encoding='utf-8')
    for directory in (ROOT/VERSION,ROOT/NETWORK_RELEASE):(directory/'README.md').write_bytes(REPORT.read_bytes())
    script=COPY.replace("=='0.1.2'","=='"+result['network']+"'").replace('BMI30_NETWORK_STABILITY_2026-10-05_RU.md','BMI30_GROUP_REALTIME_2026-10-05_RU.md')
    def copy(board):
        inv=json.loads((WORK/(board+'-inventory-after.json')).read_text());results=[]
        for root in inv['roots']:
            data=json.loads(remote(HOSTS[board],script,{'host':HOSTS[board],'live':inv['root'],'device':root['device'],
              'uuid':root.get('uuid'),'doc':base64.b64encode(REPORT.read_bytes()).decode()},timeout=35));results.append(data)
            print(json.dumps(data),flush=True)
        (WORK/(board+'-report-copied.json')).write_text(json.dumps(results,indent=2))
    with concurrent.futures.ThreadPoolExecutor(max_workers=5) as pool:list(pool.map(copy,HOSTS))

if __name__=='__main__':main()
